-- Initial PostgreSQL schema and public catalog derived from the repository migrations.

CREATE TABLE "addresses" (
	"id" text PRIMARY KEY NOT NULL,
	"user_id" text NOT NULL,
	"data" text NOT NULL
);

CREATE TABLE admin_login_attempts(id TEXT PRIMARY KEY NOT NULL,ip_hash TEXT NOT NULL,created_at bigint NOT NULL);

CREATE TABLE admin_sessions(token_hash TEXT PRIMARY KEY NOT NULL,expires_at bigint NOT NULL,credential_hash TEXT NOT NULL);

CREATE TABLE android_admin_access (
  token_hash TEXT PRIMARY KEY,
  expires_at bigint NOT NULL
);

CREATE TABLE android_admin_challenges (
  challenge TEXT PRIMARY KEY,
  expires_at bigint NOT NULL
);


CREATE TABLE "audit_logs" (
	"id" text PRIMARY KEY NOT NULL,
	"actor" text NOT NULL,
	"action" text NOT NULL,
	"target" text NOT NULL,
	"created_at" text DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')) NOT NULL
);

CREATE TABLE booking_notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,booking_id TEXT NOT NULL,data TEXT NOT NULL,read_at TEXT,created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')));

ALTER TABLE "booking_notifications" ADD COLUMN rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE;

CREATE TABLE cafe_order_sequences (
  business_day TEXT PRIMARY KEY NOT NULL,
  last_number bigint NOT NULL CONSTRAINT positive_cafe_order_sequence CHECK (last_number > 0)
);

CREATE TABLE cafe_tables(id TEXT PRIMARY KEY,seats bigint NOT NULL CHECK(seats IN (2,4,8)),enabled bigint NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)));

CREATE TABLE "carts" (
	"user_id" text PRIMARY KEY NOT NULL,
	"data" text NOT NULL,
	"created_at" text DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')) NOT NULL
, "updated_at" text DEFAULT '' NOT NULL);

CREATE TABLE cashfree_webhook_receipts (
  mode TEXT NOT NULL CHECK(mode IN ('test','live')),
  payment_id TEXT NOT NULL,
  cashfree_order_id TEXT NOT NULL,
  amount bigint NOT NULL CHECK(amount>0),
  currency TEXT NOT NULL,
  received_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')),
  PRIMARY KEY(mode,payment_id)
);

CREATE TABLE "categories" (
	"id" text PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"position" bigint DEFAULT 0 NOT NULL,
	"enabled" bigint DEFAULT 1 NOT NULL,
	"image" text DEFAULT '' NOT NULL
);

CREATE TABLE order_push_subscriptions (
 id TEXT PRIMARY KEY NOT NULL,
 user_id TEXT NOT NULL,
 subscription TEXT NOT NULL,
 created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE "orders" (
	"id" text PRIMARY KEY NOT NULL,
	"user_id" text NOT NULL,
	"idempotency_key" text NOT NULL,
	"status" text DEFAULT 'pending' NOT NULL,
	"fulfillment" text NOT NULL,
	"payment_status" text DEFAULT 'unpaid' NOT NULL,
	"subtotal" bigint NOT NULL,
	"tax" bigint NOT NULL,
	"discount" bigint NOT NULL,
	"fee" bigint NOT NULL,
	"total" bigint NOT NULL,
	"currency" text NOT NULL,
	"contact" text NOT NULL,
	"created_at" text DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')) NOT NULL
, checkout_payment_method TEXT, order_number TEXT);

ALTER TABLE "orders" ADD COLUMN rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE;

CREATE TABLE payment_intents (
 id TEXT PRIMARY KEY,
 order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),
 user_id TEXT NOT NULL,
 provider_order_id TEXT UNIQUE,
 amount bigint NOT NULL CHECK(amount > 0),
 currency TEXT NOT NULL CHECK(currency = 'INR'),
 state TEXT NOT NULL DEFAULT 'creating' CHECK(state IN ('creating','ready','paid','review')),
 created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'))
, provider TEXT NOT NULL DEFAULT 'razorpay', mode TEXT NOT NULL DEFAULT 'test', merchant_order_id TEXT, checkout_url TEXT, expires_at bigint, cashfree_order_id TEXT);

CREATE TABLE "payments" (
	"id" text PRIMARY KEY NOT NULL,
	"order_id" text NOT NULL,
	"amount" bigint NOT NULL,
	"method" text NOT NULL,
	"reference" text NOT NULL,
	"verified_by" text NOT NULL,
	"created_at" text DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')) NOT NULL,
	FOREIGN KEY ("order_id") REFERENCES "orders"("id") ON UPDATE no action ON DELETE no action
);

ALTER TABLE "payments" ADD COLUMN rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE;

CREATE TABLE paypal_test_checkouts (
 id TEXT PRIMARY KEY, order_id TEXT NOT NULL UNIQUE REFERENCES orders(id), user_id TEXT NOT NULL,
 client_id TEXT NOT NULL, provider_order_id TEXT UNIQUE, capture_id TEXT UNIQUE,
 state TEXT NOT NULL DEFAULT 'creating' CHECK(state IN ('creating','ready','verified')),
 created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')), verified_at TEXT
);

CREATE TABLE phone_accounts(phone TEXT PRIMARY KEY NOT NULL,user_id TEXT UNIQUE NOT NULL);

CREATE TABLE phone_challenges(id TEXT PRIMARY KEY NOT NULL,phone TEXT NOT NULL,phone_hash TEXT NOT NULL,ip_hash TEXT NOT NULL,created_at bigint NOT NULL,expires_at bigint NOT NULL,attempts bigint NOT NULL DEFAULT 0,sent bigint NOT NULL DEFAULT 0);

CREATE TABLE phone_sessions(token_hash TEXT PRIMARY KEY NOT NULL,user_id TEXT NOT NULL,expires_at bigint NOT NULL);

CREATE TABLE pin_login_attempts (
 id TEXT PRIMARY KEY,
 phone_hash TEXT NOT NULL,
 ip_hash TEXT NOT NULL,
 created_at bigint NOT NULL
);

CREATE TABLE pin_reset_challenges (
  token_hash TEXT PRIMARY KEY,
  phone TEXT NOT NULL,
  account_hash TEXT NOT NULL,
  expires_at bigint NOT NULL,
  attempts bigint NOT NULL DEFAULT 0,
  checking bigint NOT NULL DEFAULT 0
);

CREATE TABLE prepaid_checkouts (
  id TEXT PRIMARY KEY NOT NULL,
  order_id TEXT NOT NULL UNIQUE,
  user_id TEXT NOT NULL,
  idempotency_key TEXT NOT NULL UNIQUE,
  fulfillment TEXT NOT NULL,
  total bigint NOT NULL CHECK (total > 0),
  currency TEXT NOT NULL CHECK (currency = 'INR'),
  contact TEXT NOT NULL,
  quote TEXT NOT NULL,
  cart_snapshot TEXT NOT NULL,
  stock_holds TEXT NOT NULL,
  state TEXT NOT NULL DEFAULT 'creating' CHECK (state IN ('creating','ready','paid','expired')),
  provider_session_id TEXT UNIQUE,
  checkout_url TEXT,
  expires_at bigint,
  created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'))
, provider TEXT NOT NULL DEFAULT 'stripe' CHECK(provider IN ('stripe','cashfree')), mode TEXT NOT NULL DEFAULT 'test'
  CHECK(mode='test' OR (mode='live' AND provider='cashfree')), cashfree_order_id TEXT);

CREATE TABLE "products" (
	"id" text PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"category_id" text NOT NULL,
	"price" bigint,
	"inventory" bigint,
	"available" bigint DEFAULT 0 NOT NULL,
	"archived" bigint DEFAULT 0 NOT NULL,
	"data" text NOT NULL,
	"created_at" text DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')) NOT NULL, "updated_at" text DEFAULT '' NOT NULL,
	FOREIGN KEY ("category_id") REFERENCES "categories"("id") ON UPDATE no action ON DELETE no action,
	CONSTRAINT "product_price_nonnegative" CHECK("products"."price" IS NULL OR "products"."price" >= 0),
	CONSTRAINT "inventory_nonnegative" CHECK("products"."inventory" IS NULL OR "products"."inventory" >= 0)
);

CREATE TABLE "profiles" (
	"id" text PRIMARY KEY NOT NULL,
	"email" text NOT NULL,
	"name" text DEFAULT '' NOT NULL,
	"phone" text DEFAULT '' NOT NULL,
	"disabled" bigint DEFAULT 0 NOT NULL,
	"created_at" text DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')) NOT NULL
, avatar TEXT NOT NULL DEFAULT '', date_of_birth TEXT NOT NULL DEFAULT '', gender TEXT NOT NULL DEFAULT '' CHECK (gender IN ('', 'male', 'female', 'nonbinary', 'undisclosed')));

CREATE TABLE razorpay_test_checkouts (
 id TEXT PRIMARY KEY,
 order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),
 user_id TEXT NOT NULL,
 amount bigint NOT NULL CHECK(amount>0),
 currency TEXT NOT NULL CHECK(currency='INR'),
 key_id TEXT NOT NULL CHECK(key_id LIKE 'rzp_test_%'),
 provider_order_id TEXT UNIQUE,
 payment_id TEXT UNIQUE,
 state TEXT NOT NULL DEFAULT 'creating' CHECK(state IN ('creating','ready','verified')),
 created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')),
 verified_at TEXT
);

CREATE TABLE "settings" (
	"id" text PRIMARY KEY NOT NULL,
	"data" text NOT NULL
);

ALTER TABLE "settings" ADD COLUMN rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE;

CREATE TABLE "subscription_catalog"(
 id TEXT PRIMARY KEY,
 name TEXT NOT NULL,
 amount bigint NOT NULL CHECK(amount BETWEEN 100 AND 100000000),
 credits bigint NOT NULL CHECK(credits BETWEEN 1 AND 3660),
 days bigint NOT NULL CHECK(days BETWEEN 1 AND 730),
 enabled bigint NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),
 archived bigint NOT NULL DEFAULT 0 CHECK(archived IN (0,1)),
 revision bigint NOT NULL DEFAULT 1,
 item_scope TEXT NOT NULL DEFAULT 'coffee' CHECK(item_scope IN ('coffee','menu')),
 included_items TEXT NOT NULL DEFAULT '[]'
);

ALTER TABLE "subscription_catalog" ADD COLUMN rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE;

CREATE TABLE subscription_code_attempts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,day TEXT NOT NULL);

CREATE TABLE subscription_extended_purchases(user_id TEXT NOT NULL,plan_id TEXT NOT NULL CHECK(plan_id='two_month'),order_id TEXT PRIMARY KEY REFERENCES orders(id),created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')));

CREATE TABLE subscription_item_code_attempts (
 id TEXT PRIMARY KEY NOT NULL,
 user_id TEXT NOT NULL,
 attempted_at bigint NOT NULL
);

CREATE TABLE subscription_plan_test_purchases (
 user_id TEXT NOT NULL,
 plan_id TEXT NOT NULL CHECK(plan_id IN ('weekly','monthly')),
 order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),
 created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')),
 PRIMARY KEY(user_id,plan_id)
);

CREATE TABLE subscription_purchase_snapshots(order_id TEXT PRIMARY KEY REFERENCES orders(id),user_id TEXT NOT NULL,plan_id TEXT NOT NULL,name TEXT NOT NULL,amount bigint NOT NULL,credits bigint NOT NULL,days bigint NOT NULL,revision bigint NOT NULL,created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')), item_scope TEXT NOT NULL DEFAULT 'coffee', included_items TEXT NOT NULL DEFAULT '[]');

CREATE TABLE subscription_redemption_checks (
 order_id TEXT PRIMARY KEY REFERENCES orders(id),
 valid bigint NOT NULL CHECK(valid=1)
);

CREATE TABLE subscription_renewal_purchases (
 user_id TEXT NOT NULL,
 plan_id TEXT NOT NULL CHECK(plan_id IN ('weekly','monthly')),
 order_id TEXT PRIMARY KEY REFERENCES orders(id),
 created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE subscription_test_purchases (
 user_id TEXT PRIMARY KEY,
 order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),
 created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE "suggestions" (
	"id" text PRIMARY KEY NOT NULL,
	"user_id" text NOT NULL,
	"status" text DEFAULT 'pending' NOT NULL,
	"data" text NOT NULL,
	"created_at" text DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')) NOT NULL
);

CREATE TABLE table_booking_payments (
 id TEXT PRIMARY KEY NOT NULL,
 user_id TEXT NOT NULL REFERENCES profiles(id),
 booking TEXT NOT NULL,
 start_at bigint NOT NULL,
 end_at bigint NOT NULL,
 amount bigint NOT NULL CHECK(amount=10000),
 state TEXT NOT NULL DEFAULT 'creating' CHECK(state IN ('creating','ready','paid','expired','review')),
 provider_session_id TEXT UNIQUE,
 checkout_url TEXT,
 payment_reference TEXT UNIQUE,
 created_at bigint NOT NULL DEFAULT (floor(extract(epoch FROM statement_timestamp()))::bigint)
, provider TEXT NOT NULL DEFAULT 'stripe' CHECK(provider IN ('stripe','cashfree')), mode TEXT NOT NULL DEFAULT 'test'
  CHECK(mode='test' OR (mode='live' AND provider='cashfree')), checkout_amount bigint
  CHECK(checkout_amount IS NULL OR checkout_amount >= 100), cashfree_order_id TEXT);

CREATE TABLE table_bookings (
 id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES profiles(id),date TEXT NOT NULL,time TEXT NOT NULL,
 guests bigint NOT NULL CHECK(guests BETWEEN 1 AND 20),purpose TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','declined','cancelled')),
 created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'))
, table_ids TEXT NOT NULL DEFAULT '[]', start_at bigint, end_at bigint);

CREATE TABLE tester_sessions (token_hash TEXT PRIMARY KEY NOT NULL,user_id TEXT NOT NULL,expires_at bigint NOT NULL,created_at bigint NOT NULL,ip_hash TEXT NOT NULL);

CREATE TABLE "uploads" (
	"id" text PRIMARY KEY NOT NULL,
	"user_id" text NOT NULL,
	"mime" text NOT NULL,
	"size" bigint NOT NULL,
	"created_at" text DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')) NOT NULL
);

CREATE TABLE admin_order_chat_reads (
  staff_id TEXT NOT NULL,
  order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  last_message_id bigint NOT NULL DEFAULT 0 CHECK(last_message_id >= 0),
  PRIMARY KEY(staff_id, order_id)
);

CREATE TABLE cafe_table_schedule (
  id TEXT PRIMARY KEY NOT NULL DEFAULT (replace(gen_random_uuid()::text, '-', '')),
  table_id TEXT NOT NULL REFERENCES cafe_tables(id),
  customer_id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK(kind IN ('booking','hold','scan','visit')),
  source_id TEXT,
  booking_id TEXT,
  start_at bigint NOT NULL,
  end_at bigint NOT NULL CHECK(end_at>start_at),
  expires_at bigint,
  closed_at bigint
);

CREATE TABLE coffee_subscriptions (
 id TEXT PRIMARY KEY,
 user_id TEXT NOT NULL,
 payment_id TEXT NOT NULL UNIQUE REFERENCES payments(id),
 plan_name TEXT NOT NULL DEFAULT '1 Week Subscription',
 total_credits bigint NOT NULL CHECK(total_credits = 8),
 starts_at TEXT NOT NULL,
 expires_at TEXT NOT NULL,
 revoked bigint NOT NULL DEFAULT 0 CHECK(revoked IN (0,1)),
 created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'))
, bonus_credits bigint NOT NULL DEFAULT 0 CHECK(bonus_credits IN (0,26)), plan_id TEXT NOT NULL DEFAULT 'weekly', extended_credits bigint NOT NULL DEFAULT 0 CHECK(extended_credits IN (0,52)), purchased_credits bigint CHECK(purchased_credits BETWEEN 1 AND 3660), item_scope TEXT NOT NULL DEFAULT 'coffee', included_items TEXT NOT NULL DEFAULT '[]');

CREATE TABLE "favorites" (
	"id" text PRIMARY KEY NOT NULL,
	"user_id" text NOT NULL,
	"product_id" text NOT NULL,
	FOREIGN KEY ("product_id") REFERENCES "products"("id") ON UPDATE no action ON DELETE no action
);

CREATE TABLE order_chat_messages (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  sender_id TEXT NOT NULL,
  sender_role TEXT NOT NULL CHECK (sender_role IN ('customer', 'staff')),
  request_id TEXT NOT NULL,
  message TEXT NOT NULL CHECK (length(message) BETWEEN 1 AND 500),
  created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (order_id, sender_id, sender_role, request_id)
);

CREATE TABLE "order_events" (
	"id" text PRIMARY KEY NOT NULL,
	"order_id" text NOT NULL,
	"status" text NOT NULL,
	"actor" text NOT NULL,
	"created_at" text DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')) NOT NULL,
	FOREIGN KEY ("order_id") REFERENCES "orders"("id") ON UPDATE no action ON DELETE no action
);

ALTER TABLE "order_events" ADD COLUMN rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE;

CREATE TABLE "order_items" (
	"id" text PRIMARY KEY NOT NULL,
	"order_id" text NOT NULL,
	"product_id" text NOT NULL,
	"name" text NOT NULL,
	"quantity" bigint NOT NULL,
	"unit_price" bigint NOT NULL,
	"selections" text NOT NULL,
	"instructions" text DEFAULT '' NOT NULL,
	FOREIGN KEY ("order_id") REFERENCES "orders"("id") ON UPDATE no action ON DELETE no action,
	FOREIGN KEY ("product_id") REFERENCES "products"("id") ON UPDATE no action ON DELETE no action
);

CREATE TABLE pin_accounts (
 phone TEXT PRIMARY KEY,
 user_id TEXT NOT NULL UNIQUE REFERENCES profiles(id),
 pin_salt TEXT NOT NULL,
 pin_hash TEXT NOT NULL,
 created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE pin_sessions (
 token_hash TEXT PRIMARY KEY,
 user_id TEXT NOT NULL REFERENCES profiles(id),
 expires_at bigint NOT NULL,
 created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE "subscription_daily_codes" (
 user_id TEXT NOT NULL,
 day TEXT NOT NULL,
 subscription_id TEXT NOT NULL REFERENCES coffee_subscriptions(id),
 code_hash TEXT NOT NULL,
 expires_at bigint NOT NULL,
 redeemed_order_id TEXT UNIQUE REFERENCES orders(id),
 PRIMARY KEY(user_id,day,subscription_id),
 UNIQUE(user_id,day,code_hash)
);

CREATE TABLE subscription_item_codes (
 id TEXT PRIMARY KEY NOT NULL,
 user_id TEXT NOT NULL,
 subscription_id TEXT NOT NULL REFERENCES coffee_subscriptions(id),
 code_hash TEXT NOT NULL,
 expires_at bigint NOT NULL,
 retired bigint NOT NULL DEFAULT 0,
 redeemed_order_id TEXT UNIQUE REFERENCES orders(id),
 UNIQUE(user_id,code_hash)
);

ALTER TABLE "subscription_item_codes" ADD COLUMN rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE;

CREATE TABLE coffee_redemptions (
 id TEXT PRIMARY KEY,
 subscription_id TEXT NOT NULL REFERENCES coffee_subscriptions(id),
 order_id TEXT NOT NULL REFERENCES orders(id),
 credits bigint NOT NULL CHECK(credits BETWEEN 1 AND 8),
 reversed_at TEXT,
 created_at TEXT NOT NULL DEFAULT (to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')),
 UNIQUE(subscription_id,order_id)
);


