CREATE INDEX pin_sessions_user ON pin_sessions(user_id);

CREATE UNIQUE INDEX prepaid_cashfree_order ON prepaid_checkouts(cashfree_order_id) WHERE cashfree_order_id IS NOT NULL;

CREATE INDEX subscription_code_attempt_budget ON subscription_code_attempts(user_id,day);

CREATE INDEX subscription_extended_user ON subscription_extended_purchases(user_id,plan_id,created_at);

CREATE INDEX subscription_item_code_attempt_budget ON subscription_item_code_attempts(user_id,attempted_at);

CREATE UNIQUE INDEX subscription_item_code_pending ON subscription_item_codes(subscription_id)
 WHERE retired=0 AND redeemed_order_id IS NULL;

CREATE INDEX subscription_item_codes_by_pass ON subscription_item_codes(user_id,subscription_id);

CREATE INDEX subscription_snapshot_user ON subscription_purchase_snapshots(user_id,plan_id,created_at);

CREATE INDEX table_booking_payments_user ON table_booking_payments(user_id,state,start_at,end_at);

CREATE UNIQUE INDEX table_bookings_active_slot ON table_bookings(user_id,date,time) WHERE status IN ('pending','confirmed');

CREATE INDEX table_bookings_user ON table_bookings(user_id,date);

SELECT setval('public.subscription_catalog_rowid_seq'::regclass,'3'::bigint,true);
